FoamFile { version 2.0; format ascii; class dictionary; location "system"; object controlDict; }
application simpleFoam;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 500;
deltaT 1;
writeControl timeStep;
writeInterval 50;
purgeWrite 0;
writeFormat ascii;
writePrecision 6;
writeCompression off;
timeFormat general;
timePrecision 6;
runTimeModifiable true;

FoamFile { version 2.0; format ascii; class dictionary; location "system"; object fvSchemes; }
ddtSchemes  { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes  { default none; div(phi,U) Gauss upwind; div(phi,k) Gauss upwind; div(phi,omega) Gauss upwind; div((nuEff*dev2(T(grad(U))))) Gauss linear; }
laplacianSchemes { default Gauss linear corrected 0.5; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected 0.5; }

FoamFile { version 2.0; format ascii; class dictionary; location "system"; object fvSolution; }
solvers
{
    p           { solver GAMG; smoother DICGaussSeidel; tolerance 1e-6; relTol 0.01; }
    pFinal      { $p; relTol 0; }
    U           { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-6; relTol 0; }
    k           { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-6; relTol 0; }
    omega       { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-6; relTol 0; }
}
SIMPLE
{
    nNonOrthogonalCorrectors 2;
    consistent yes;
    pRefCell 0;
    pRefValue 0;
}
relaxationFactors
{
    fields { p 0.3; }
    equations { U 0.7; k 0.7; omega 0.7; }
}

